const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const env = String(payload.environment || payload.env || 'production').toLowerCase();
const repo = String(payload.repository || payload.repo || 'logicintelligencetechnologies').trim();
const commit = String(payload.commit || payload.sha || 'unknown').substring(0, 7);
const author = String(payload.author || payload.actor || 'automated').trim();
const failedStep = String(payload.failedStep || payload.step || 'build').trim();
const errorMessage = String(payload.errorMessage || payload.error || 'Deployment pipeline check failed').trim();

const isProd = env.includes('prod');
const severity = isProd ? 'P0_CRITICAL' : 'P2_ELEVATED';

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    incident: {
      severity,
      environment: env,
      repository: repo,
      commitSha: commit,
      author,
      failedStep,
      errorMessage,
      detectedAt: new Date().toISOString(),
      escalationTarget: 'Vikash Saravanan (Lead System Engineer)'
    }
  }
}];

const item = $input.first().json;
const inc = item.incident;

const alertCard = {
  title: `🚨 [${inc.severity}] Deployment Failed on ${inc.environment.toUpperCase()}`,
  repository: inc.repository,
  commit: inc.commitSha,
  author: inc.author,
  step: inc.failedStep,
  summary: inc.errorMessage,
  actionRequired: inc.severity === 'P0_CRITICAL' ? 'Immediate rollback or fast-forward patch required' : 'Review CI failure logs',
  notificationDispatchedTo: ['Ops Console', 'Lead Engineer Incident Feed']
};

return [{
  json: {
    eventId: item.eventId,
    status: 'alert_dispatched',
    incident: inc,
    alertCard
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'alert_dispatched',
  detail: { incident: item.json.incident, alertCard: item.json.alertCard }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
